package at.dergeorg.drawboard.plugins.domain.frame

import at.dergeorg.drawboard.plugins.domain.manifest.NetworkHosts
import at.dergeorg.drawboard.plugins.domain.plugins.model.FrameDocument
import at.dergeorg.drawboard.plugins.domain.plugins.model.InstalledPlugin

/**
 * The document a plugin runs in (S3.3, S3.6): GENERATED by the server, never taken from the ZIP - the bundle has no
 * HTML. It holds nothing but the entry module with its `integrity` hash, and is served with a CSP of its own:
 *
 * * `sandbox allow-scripts` and `default-src 'none'` - the frame has an opaque origin, so `'self'` would match nothing;
 *   every source is explicit and PATH-SCOPED to this plugin's own asset base, so the frame can not load another plugin's
 *   or the app's scripts (M3 contract review);
 * * `connect-src` is the list of hosts the admin granted with `network`, as `https://host[:port]`, else `'none'`;
 * * no `'wasm-unsafe-eval'`: WebAssembly is not part of plugin API 1;
 * * `frame-ancestors` is the app origin: only the board host may embed it.
 *
 * [assetOrigin] is the origin the assets are served from (the plugin origin if there is one, else the app origin),
 * [assetBase] the same plugin's base as the browser addresses it (a path, or a URL on the plugin origin).
 */
internal object FrameDocuments {

    fun create(plugin: InstalledPlugin, assetOrigin: String, assetBase: String, appOrigin: String): FrameDocument {
        val source = assetOrigin + plugin.assetPath // scheme://host/plugin-assets/<id>/<version>/<sha256>/
        val network = plugin.grantedCapabilities.firstOrNull { it.name == "network" }?.value
        val hosts = network?.let { (NetworkHosts.parse(it) as? NetworkHosts.Result.Valid)?.hosts }.orEmpty()
        val connect = NetworkHosts.connectSources(hosts).joinToString(" ").ifEmpty { "'none'" }
        val csp = listOf(
            "sandbox allow-scripts",
            "default-src 'none'",
            "script-src $source",
            "style-src $source 'unsafe-inline'",
            "img-src $source data: blob:",
            "font-src $source",
            "connect-src $connect",
            "base-uri 'none'",
            "form-action 'none'",
            "frame-ancestors $appOrigin",
        ).joinToString("; ")
        val src = escape(assetBase + plugin.entry)
        val html = "<!doctype html><meta charset=\"utf-8\">" +
            "<script type=\"module\" src=\"$src\" integrity=\"${escape(plugin.integrity)}\" crossorigin=\"anonymous\"></script>"
        return FrameDocument(html, csp)
    }

    private fun escape(text: String) = text.replace("&", "&amp;").replace("\"", "&quot;").replace("<", "&lt;").replace(">", "&gt;")
}
